package local.cleartv.mobile;
import com.jcraft.jsch.*;import android.content.Context;import java.io.*;import java.net.URI;import java.util.*;import org.json.*;
/** Own-app-only Web Inspector through the authenticated Developer Mode SSH tunnel. */
final class LgControl implements AutoCloseable {
 private JSch ssh;private Session session;private Inspector inspector;
 LgControl(Context c,String ip)throws Exception{
  if(!LgInstallProtocol.local(ip))throw new IOException("Select your LG TV first.");byte[] record=new Vault(c).get(LgInstaller.credentialName(ip));if(record==null)throw new IOException("اربط LG بالمفتاح من صفحة التوصيل أولًا.");
  byte[] key=null,phrase=null;String stage="credentials";
  try{JSONObject value=new JSONObject(new String(record,"UTF-8"));key=Base64.getDecoder().decode(value.getString("key"));phrase=Base64.getDecoder().decode(value.getString("phrase"));String expected=c.getSharedPreferences("lg-hosts",0).getString(ip,"");if(expected.isEmpty())throw new IOException("LG host trust is missing. Pair again.");
   ssh=new JSch();ssh.addIdentity("Morph LG",key,null,phrase);ssh.setHostKeyRepository(new HostKeyRepository(){public int check(String h,byte[] b){return expected.equals(LgInstallProtocol.fingerprint(b))?OK:CHANGED;}public void add(HostKey h,UserInfo u){}public void remove(String h,String t){}public void remove(String h,String t,byte[] k){}public String getKnownHostsRepositoryID(){return "Pinned LG";}public HostKey[] getHostKey(){return new HostKey[0];}public HostKey[] getHostKey(String h,String t){return getHostKey();}});
   stage="SSH 9922: فعّل Developer Mode وتأكد أن الموبايل والشاشة على نفس الشبكة";session=ssh.getSession("prisoner",ip,9922);LgSsh.configure(session);session.setTimeout(15000);session.connect(15000);
   stage="Web Inspector 9998: افتح Morph TV على الشاشة ثم أعد الاتصال";int local=session.setPortForwardingL("127.0.0.1",0,"127.0.0.1",9998);for(String endpoint:new String[]{"/json/list","/json","/pagelist.json"}){JSONArray targets;try{targets=new JSONArray(Network.get("http://127.0.0.1:"+local+endpoint,5000));}catch(Exception unavailable){continue;}for(int i=0;i<targets.length();i++){String path=LgInspectorTarget.socket(targets.getJSONObject(i),ip,LgInstallProtocol.APP);if(path==null)continue;Inspector candidate=null;try{candidate=new Inspector("ws://127.0.0.1:"+local+path);if(Boolean.TRUE.equals(candidate.evaluate("!!(window.MorphLG&&window.ClearTV&&webOS.fetchAppId()==='"+LgInstallProtocol.APP+"')"))){inspector=candidate;break;}}catch(Exception unavailable){/* A stale inspector page must not prevent trying the next own-app target. */}finally{if(candidate!=null&&candidate!=inspector)candidate.close();}}if(inspector!=null)break;}
   if(inspector==null)throw new IOException("افتح Morph TV LG Preview على الشاشة ثم اضغط اتصال. الفحص لا يفتح أي تطبيق تلقائيًا.");
   try{syncPlusIdentity(c,expected);}catch(Exception ignored){}
   // Also silence the old preview's pending update check when connecting to it.
   inspector.evaluate("(function(){localStorage.setItem('tvmorph.updateAlerts','off');var b=document.getElementById('release-alert');if(b){b.remove();if(window.ClearTV&&ClearTV.focusDefault)ClearTV.focusDefault();}return true;})()");
  }catch(Exception e){close();throw new IOException("تعذّر ربط LG — "+stage+". تأكد من صلاحية Developer Mode، وأعد الربط بالمفتاح إذا تغيّر. سبب الفشل: "+failure(e)+"",e);}finally{Arrays.fill(record,(byte)0);if(key!=null)Arrays.fill(key,(byte)0);if(phrase!=null)Arrays.fill(phrase,(byte)0);}
 }
 private static String failure(Exception e){
  if(e instanceof com.jcraft.jsch.JSchException)return LgSsh.failure((com.jcraft.jsch.JSchException)e);
  if(e instanceof java.net.SocketTimeoutException)return "انتهت مهلة الاتصال بالشاشة. راجع الشبكة وافتح Morph TV على LG.";
  if(e instanceof java.net.ConnectException)return "خدمة الاتصال غير متاحة. افتح Developer Mode وMorph TV على الشاشة.";
  return "لم يتم تأكيد اتصال التطبيق. لو حفظت المفتاح بالفعل، افتح Morph TV على الشاشة ثم أعد فحص الاتصال.";
 }
 private void syncPlusIdentity(Context context,String fingerprint)throws Exception{
  Vault vault=new Vault(context);String name=plusBackupName(fingerprint);Object raw=inspector.evaluate("(async function(){var p=window.MorphPlus;if(!p)return '';await p.ready;if(!p.isActive())return '';return JSON.stringify({device:localStorage.getItem('morph.plus.device'),token:localStorage.getItem('morph.plus.token')});})()");
  if(raw instanceof String&&!((String)raw).isEmpty()){byte[] bytes=((String)raw).getBytes("UTF-8");try{JSONObject value=new JSONObject((String)raw);if(value.optString("device").matches("[a-f0-9]{48}")&&value.optString("token").matches("[A-Za-z0-9_-]{32,128}"))vault.put(name,bytes);}finally{Arrays.fill(bytes,(byte)0);}return;}
  byte[] saved=vault.get(name);if(saved==null)return;try{JSONObject value=new JSONObject(new String(saved,"UTF-8"));if(value.optString("device").matches("[a-f0-9]{48}")&&value.optString("token").matches("[A-Za-z0-9_-]{32,128}"))inspector.evaluate("window.MorphPlus&&MorphPlus.restoreIdentity?MorphPlus.restoreIdentity("+value.toString()+"):false");}finally{Arrays.fill(saved,(byte)0);}
 }
 static String plusBackupName(String fingerprint)throws Exception{return "lg-plus-"+LgInstallProtocol.digest(fingerprint.getBytes("UTF-8"));}
 JSONArray installedApps()throws Exception{JSONObject result=LgInstallProtocol.run(session,"/usr/bin/luna-send-pub -n 1 luna://com.webos.applicationManager/dev/listApps '{\"subscribe\":false}'",false,15000);JSONArray apps=result.optJSONArray("apps"),rows=new JSONArray();if(!result.optBoolean("returnValue")||apps==null)throw new IOException("LG did not permit installed-app listing.");Set<String> seen=new HashSet<>();ChannelSftp icons=null;long[] budget={512*1024};try{try{icons=(ChannelSftp)session.openChannel("sftp");icons.connect(3000);}catch(Exception ignored){}for(int i=0;i<apps.length();i++){JSONObject a=apps.optJSONObject(i);if(a==null)continue;String id=a.optString("id"),name=a.optString("title",a.optString("name",id));if(!id.matches("[a-zA-Z0-9._-]{1,160}")||id.equals(LgInstallProtocol.APP)||!seen.add(id))continue;String icon=appIcon(icons,a,budget);rows.put(new JSONObject().put("id",id).put("name",name.isEmpty()?id:name).put("icon",icon).put("visible",!a.has("visible")||a.optBoolean("visible")).put("installed",true).put("launchable",true).put("discoverySource","developer-bridge"));}}finally{if(icons!=null)icons.disconnect();}return rows;}
 private static final Map<String,String> iconCache=Collections.synchronizedMap(new LinkedHashMap<String,String>(80,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,String> e){return size()>160;}});
 private String appIcon(ChannelSftp channel,JSONObject app,long[] budget){if(channel==null||!channel.isConnected()||budget[0]<=0)return "";String file=app.optString("icon"),folder=app.optString("folderPath");if(!file.startsWith("/"))file=folder+"/"+file;if(!(file.startsWith("/usr/palm/applications/")||file.startsWith("/media/cryptofs/apps/usr/palm/applications/")||file.startsWith("/media/developer/apps/usr/palm/applications/"))||file.contains("..")||!file.matches("[a-zA-Z0-9_./-]+\\.(png|jpg|jpeg|webp)"))return "";String cacheKey=session.getHost()+":"+file+":"+app.optString("version");String cached=iconCache.get(cacheKey);if(cached!=null)return cached;try{long size=channel.lstat(file).getSize();if(size<=0||size>65536||size>budget[0])return "";ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=channel.get(file)){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>65536)return "";bytes.write(b,0,n);}}budget[0]-=bytes.size();byte[] data=bytes.toByteArray();android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth<=0||options.outHeight<=0||options.outWidth>16384||options.outHeight>16384)return "";options.inJustDecodeBounds=false;options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>128)options.inSampleSize*=2;android.graphics.Bitmap source=android.graphics.BitmapFactory.decodeByteArray(data,0,data.length,options);if(source==null)return "";android.graphics.Bitmap small=android.graphics.Bitmap.createScaledBitmap(source,64,64,true);ByteArrayOutputStream out=new ByteArrayOutputStream();small.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);if(small!=source)small.recycle();source.recycle();String encoded="data:image/png;base64,"+android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP);iconCache.put(cacheKey,encoded);return encoded;}catch(Exception unavailable){return "";}}
 Object evaluate(String expression)throws Exception{return inspector.evaluate(expression);}
 Object json(String expression)throws Exception{Object value=evaluate("(async function(){return JSON.stringify(await ("+expression+"));})()");String s=String.valueOf(value);return s.startsWith("[")?new JSONArray(s):new JSONObject(s);}
 public void close(){if(inspector!=null)inspector.close();if(session!=null)session.disconnect();if(ssh!=null)try{ssh.removeAllIdentity();}catch(Exception ignored){}}
 static boolean saved(Context c,String ip){return c.getFileStreamPath(LgInstaller.credentialName(ip)).isFile();}
 static void forget(Context c,String ip)throws Exception{if(!LgInstallProtocol.local(ip))throw new IOException("Invalid LG address");String fingerprint=c.getSharedPreferences("lg-hosts",0).getString(ip,"");if(!fingerprint.isEmpty())c.deleteFile(plusBackupName(fingerprint));c.deleteFile(LgInstaller.credentialName(ip));c.getSharedPreferences("lg-hosts",0).edit().remove(ip).apply();}
}
